package br.gov.dere.application.d1001;
import br.gov.dere.domain.contributor.D1001; import br.gov.dere.integration.xml.XmlSupport; import java.time.LocalDate; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class D1001XmlGeneratorTest {
 @Test void geraD1001ComEstruturaOficial(){var d=new D1001("DeRE10011000000123456782026090212000000001",1,2,"dere-poc/0.1","12345678",LocalDate.of(2026,10,1),null,9,java.util.List.of(),0); var xml=assertDoesNotThrow(()->new D1001XmlGenerator().generate(d)); assertTrue(xml.contains("evtInfoContrib")); assertTrue(xml.contains("12345678")); assertDoesNotThrow(()->XmlSupport.parse(xml));}
 @Test void validaContraXsdDaNotaOrientativa() throws Exception { var d=new D1001("DeRE10011000000123456782026090212000000002",1,2,"dere-poc/0.1","12345678",LocalDate.of(2026,10,1),null,9,java.util.List.of(),0); var unsigned=new D1001XmlGenerator().generate(d); var ks=br.gov.dere.integration.signature.LocalTestCertificate.create(); var xml=new br.gov.dere.integration.signature.DereXmlSigner().sign(unsigned,ks,"changeit".toCharArray(),"dere-test"); try (var xsd=getClass().getResourceAsStream("/dere/schemas/nota_2026_001/xsd/evtInfoContrib-v1_0_1.xsd")) { assertNotNull(xsd); assertDoesNotThrow(()->XmlSupport.validate(xml,xsd)); } }
}
